import{_ as t,o as a,c as d,a2 as s}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"OpenCode","description":"通过 CC Switch 或 OpenAI Compatible 配置为 OpenCode 接入 Tokeness。","frontmatter":{"title":"OpenCode","description":"通过 CC Switch 或 OpenAI Compatible 配置为 OpenCode 接入 Tokeness。"},"headers":[],"relativePath":"integrations/opencode.md","filePath":"integrations/opencode.md","lastUpdated":1781532219000}'),o={name:"integrations/opencode.md"};function i(n,e,p,l,h,r){return a(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="opencode" tabindex="-1">OpenCode <a class="header-anchor" href="#opencode" aria-label="Permalink to &quot;OpenCode&quot;">​</a></h1><p>OpenCode 支持多模型和自定义供应商。接入 Tokeness 时选择 OpenAI Compatible，并填写 Tokeness 的 Base URL、API Key 和模型名。</p><p>通过 <a href="https://ccswitch.io/zh/docs?section=getting-started" target="_blank" rel="noreferrer">CC Switch</a> 管理 OpenCode 配置时，Claude Code、Codex、OpenCode 可以在同一个工具里切换供应商。</p><h2 id="接入信息" tabindex="-1">接入信息 <a class="header-anchor" href="#接入信息" aria-label="Permalink to &quot;接入信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>填写内容</th></tr></thead><tbody><tr><td>Provider</td><td><code>OpenAI Compatible</code> 或自定义</td></tr><tr><td>Name</td><td><code>Tokeness</code></td></tr><tr><td>Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>Tokeness 控制台创建的 Key</td></tr><tr><td>Model</td><td>从 Tokeness 模型广场复制</td></tr></tbody></table><h2 id="_1-准备-tokeness" tabindex="-1">1. 准备 Tokeness <a class="header-anchor" href="#_1-准备-tokeness" aria-label="Permalink to &quot;1. 准备 Tokeness&quot;">​</a></h2><p>在 Tokeness 控制台完成：</p><ol><li>确认钱包余额可用。</li><li>创建 OpenCode 专用 API Key。</li><li>在模型广场复制模型名。</li><li>打开使用日志，后面验证请求。</li></ol><p>Key 名称可以写成：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>opencode-local</span></span></code></pre></div><h2 id="_2-安装-opencode" tabindex="-1">2. 安装 OpenCode <a class="header-anchor" href="#_2-安装-opencode" aria-label="Permalink to &quot;2. 安装 OpenCode&quot;">​</a></h2><p>按 OpenCode 官方方式安装。常见安装命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://opencode.ai/install</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p>安装完成后确认命令可用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opencode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>如果系统提示找不到命令，关闭终端重新打开，或检查安装脚本提示的 PATH 配置。</p><h2 id="_3-通过-cc-switch-配置" tabindex="-1">3. 通过 CC Switch 配置 <a class="header-anchor" href="#_3-通过-cc-switch-配置" aria-label="Permalink to &quot;3. 通过 CC Switch 配置&quot;">​</a></h2><ol><li>打开 CC Switch。</li><li>左侧切换到 <code>OpenCode</code>。</li><li>点击右上角 <code>+</code>。</li><li>预设选择 <code>OpenAI Compatible</code>。如果没有该预设，选择自定义。</li><li>名称填写 <code>Tokeness</code>。</li><li>API Key 填写 Tokeness API Key。</li><li>Base URL 填写 <code>https://n.tokeness.io/v1</code>。</li><li>模型填写 Tokeness 模型广场中的完整模型名。</li><li>保存并启用。</li></ol><p>如果界面支持测试连接，保存后点一次测试。测试失败时，优先检查 Key、Base URL 和模型名。</p><h2 id="_4-手动填写时的对应关系" tabindex="-1">4. 手动填写时的对应关系 <a class="header-anchor" href="#_4-手动填写时的对应关系" aria-label="Permalink to &quot;4. 手动填写时的对应关系&quot;">​</a></h2><p>如果不用 CC Switch，在 OpenCode 自己的 Provider 设置里按下面关系填写：</p><table tabindex="0"><thead><tr><th>OpenCode 字段</th><th>Tokeness 填写内容</th></tr></thead><tbody><tr><td>Provider Type</td><td>OpenAI Compatible</td></tr><tr><td>API Key</td><td>Tokeness API Key</td></tr><tr><td>Base URL / Endpoint</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>Model</td><td>Tokeness 模型名</td></tr></tbody></table><p>不要选 Anthropic Provider。Tokeness 通用接口按 OpenAI 兼容格式接入。</p><h2 id="_5-启动并验证" tabindex="-1">5. 启动并验证 <a class="header-anchor" href="#_5-启动并验证" aria-label="Permalink to &quot;5. 启动并验证&quot;">​</a></h2><p>关闭当前终端，重新打开后运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opencode</span></span></code></pre></div><p>输入：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请只回复一句话，说明 OpenCode 已经接入 Tokeness。</span></span></code></pre></div><p>然后到 Tokeness 使用日志确认请求记录。</p><h2 id="_6-模型切换" tabindex="-1">6. 模型切换 <a class="header-anchor" href="#_6-模型切换" aria-label="Permalink to &quot;6. 模型切换&quot;">​</a></h2><p>OpenCode 适合同时配置多个模型。可以按用途拆分：</p><table tabindex="0"><thead><tr><th>配置</th><th>用途</th></tr></thead><tbody><tr><td>编码模型</td><td>写代码、改 bug、生成测试</td></tr><tr><td>推理模型</td><td>复杂问题分析、架构设计</td></tr><tr><td>低成本模型</td><td>文档整理、批量重命名、简单问答</td></tr></tbody></table><p>切换模型后，如果 OpenCode 没有立即生效，退出 OpenCode 后重新进入。</p><h2 id="_7-排查" tabindex="-1">7. 排查 <a class="header-anchor" href="#_7-排查" aria-label="Permalink to &quot;7. 排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>OpenCode 找不到供应商</td><td>确认 CC Switch 已保存并启用 Tokeness</td></tr><tr><td>401 Unauthorized</td><td>重新复制 API Key</td></tr><tr><td>404 Not Found</td><td>Base URL 填 <code>https://n.tokeness.io/v1</code></td></tr><tr><td>model not found</td><td>从模型广场重新复制模型名</td></tr><tr><td>自动拉模型列表失败</td><td>手动填写模型名</td></tr><tr><td>Tokeness 无日志</td><td>OpenCode 没有走 Tokeness 供应商，检查当前启用配置</td></tr><tr><td>切换后仍是旧模型</td><td>退出 OpenCode，重新打开终端</td></tr></tbody></table>',35)])])}const b=t(o,[["render",i]]);export{k as __pageData,b as default};
